const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const lakeBosutmwi = ee.Geometry.Polygon([
    [[-1.48, 6.55], [-1.48, 6.45], [-1.32, 6.45], [-1.32, 6.55]]
  ]);

  const dec2015 = ee.DateRange('2015-12-01', '2015-12-31');
  const dec2024 = ee.DateRange('2024-12-01', '2024-12-31');

  // Function to get and mask Sentinel-2 data
  function getSentinel2Collection(dateRange, geometry) {
    return ee.ImageCollection('COPERNICUS/S2_SR')
      .filterBounds(geometry)
      .filterDate(dateRange.start(), dateRange.end())
      .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 80))
      .map(function(image) {
        // Cloud masking using QA60 band
        const qa = image.select('QA60');
        const cloudBitMask = 1 << 10;
        const cirrusBitMask = 1 << 11;
        const mask = qa.bitwiseAnd(cloudBitMask).eq(0)
          .and(qa.bitwiseAnd(cirrusBitMask).eq(0));
        return image.updateMask(mask);
      });
  }

  // Function to calculate NDCI for Sentinel-2
  function addNDCI(image) {
    // NDCI = (B5 - B4) / (B5 + B4)
    return image.addBands(
      image.normalizedDifference(['B5', 'B4']).rename('NDCI')
    );
  }

  // 2. Data Acquisition & Check
  let col2015 = getSentinel2Collection(dec2015, lakeBosutmwi).map(addNDCI);
  let col2024 = getSentinel2Collection(dec2024, lakeBosutmwi).map(addNDCI);

  // Check collection sizes
  const size2015 = col2015.size().getInfo();
  const size2024 = col2024.size().getInfo();

  console.log(`2015 Images: ${size2015}, 2024 Images: ${size2024}`);

  // Fallback to Landsat if Sentinel-2 has no images
  if (size2015 === 0 || size2024 === 0) {
    console.log("Trying Landsat 8/9 as fallback...");

    // Function for Landsat collection
    function getLandsatCollection(dateRange, geometry) {
      const landsat8 = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
        .filterBounds(geometry)
        .filterDate(dateRange.start(), dateRange.end())
        .filter(ee.Filter.lt('CLOUD_COVER', 80));

      const landsat9 = ee.ImageCollection('LANDSAT/LC09/C02/T1_L2')
        .filterBounds(geometry)
        .filterDate(dateRange.start(), dateRange.end())
        .filter(ee.Filter.lt('CLOUD_COVER', 80));

      return landsat8.merge(landsat9)
        .map(function(image) {
          // Apply scaling factors for Landsat
          const opticalBands = image.select('SR_B.').multiply(0.0000275).add(-0.2);
          const thermalBands = image.select('ST_B.*').multiply(0.00341802).add(149.0);
          return ee.Image.cat([opticalBands, thermalBands])
            .copyProperties(image, ['system:time_start']);
        });
    }

    if (size2015 === 0) {
      col2015 = getLandsatCollection(dec2015, lakeBosutmwi);
      // Landsat NDCI approximation: (B5 - B4) / (B5 + B4)
      col2015 = col2015.map(function(img) {
        return img.addBands(
          img.normalizedDifference(['SR_B5', 'SR_B4']).rename('NDCI')
        );
      });
    }

    if (size2024 === 0) {
      col2024 = getLandsatCollection(dec2024, lakeBosutmwi);
      col2024 = col2024.map(function(img) {
        return img.addBands(
          img.normalizedDifference(['SR_B5', 'SR_B4']).rename('NDCI')
        );
      });
    }

    // Re-check sizes
    const newSize2015 = col2015.size().getInfo();
    const newSize2024 = col2024.size().getInfo();

    console.log(`After fallback - 2015: ${newSize2015}, 2024: ${newSize2024}`);

    if (newSize2015 === 0 || newSize2024 === 0) {
      console.log("<answer>C1</answer>");
      return;
    }
  }

  // 3. Processing - Create median composites
  const comp2015 = col2015.select('NDCI').median();
  const comp2024 = col2024.select('NDCI').median();

  // Check valid pixel counts
  const reducer = ee.Reducer.count();
  const count2015 = comp2015.reduceRegion({
    reducer: reducer,
    geometry: lakeBosutmwi,
    scale: 100,
    maxPixels: 1e9
  }).get('NDCI').getInfo();

  const count2024 = comp2024.reduceRegion({
    reducer: reducer,
    geometry: lakeBosutmwi,
    scale: 100,
    maxPixels: 1e9
  }).get('NDCI').getInfo();

  console.log(`Valid pixels 2015: ${count2015}, 2024: ${count2024}`);

  if (count2015 === 0 || count2024 === 0) {
    console.log("<answer>C2</answer>");
    return;
  }

  // 4. Calculation - Get mean NDCI values
  const meanReducer = ee.Reducer.mean();
  const ndci2015 = comp2015.reduceRegion({
    reducer: meanReducer,
    geometry: lakeBosutmwi,
    scale: 100,
    maxPixels: 1e9
  }).get('NDCI').getInfo();

  const ndci2024 = comp2024.reduceRegion({
    reducer: meanReducer,
    geometry: lakeBosutmwi,
    scale: 100,
    maxPixels: 1e9
  }).get('NDCI').getInfo();

  console.log(`NDCI 2015: ${ndci2015?.toFixed(4)}, 2024: ${ndci2024?.toFixed(4)}`);

  // 5. Validation & Final Answer
  if (ndci2015 === null || ndci2024 === null || 
      isNaN(ndci2015) || isNaN(ndci2024) ||
      Math.abs(ndci2015) > 1 || Math.abs(ndci2024) > 1) {
    console.log("<answer>C3</answer>");
  } else {
    // If 2024 NDCI is greater than 2015 by more than 0.01 (meaningful difference for NDCI)
    const threshold = 0.01;
    if (ndci2024 - ndci2015 > threshold) {
      console.log("<answer>A</answer>");
    } else {
      console.log("<answer>B</answer>");
    }
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
